(()=>{"use strict";const q=id=>document.getElementById(id),fmt=x=>Number.isFinite(x)?x.toFixed(2):"—";function draw(){const host=q("n53PileEditor");if(!host){setTimeout(draw,180);return}let box=q("nR20PileAxial");if(!box){box=document.createElement("aside");box.id="nR20PileAxial";box.setAttribute("aria-live","polite");host.after(box)}const cp=window.NCYCP005,active=typeof R7!=="undefined"&&R7.active,valid=active&&!R7.dirty&&!!R7.result;if(!valid){box.hidden=!active;box.innerHTML="<h4>แรงแกนแนวดิ่งต่อเข็ม</h4><p>กดคำนวณและตรวจแรงหัวเข็มเพื่อดูค่าสูงสุดของเข็มแต่ละต้น</p>";return}const a=cp?.fresh?.()?cp.state.snapshot:null,piles=a?.piles||[],cap=cp?.configuration?.().capacity;if(!piles.length){box.hidden=false;box.innerHTML="<h4>แรงแกนแนวดิ่งต่อเข็ม</h4><p>เปิด “ตรวจแรงหัวเข็มชุดปัจจุบัน” เพื่อแสดงผลจากกรณีเดียวกัน</p>";return}const asd=piles.filter(p=>p.basis==="ASD"),compress=asd.flatMap(p=>p.rows.filter(r=>r.R>=0).map(r=>({caseId:p.caseId,...r}))),uplift=asd.flatMap(p=>p.rows.filter(r=>r.R<0).map(r=>({caseId:p.caseId,...r})));const peak=compress.reduce((a2,b)=>!a2||b.R>a2.R?b:a2,null),lift=uplift.reduce((a2,b)=>!a2||b.R<a2.R?b:a2,null);const rated=cap?.basis==="SLS"&&Number(cap.compression)>0?Number(cap.compression):NaN,dc=peak&&Number.isFinite(rated)?peak.R/rated:NaN;const source=String(cap?.ref||"").trim(),status=!source?"รอรุ่นและเอกสารผู้ผลิต":!Number.isFinite(dc)?"รอแรงใช้งาน (ASD) และกำลังที่เทียบกันได้":dc>1?"NG · แรงอัดเกินค่าที่กรอก":"เทียบแรงอัดได้ · ตรวจเงื่อนไขผู้ผลิต";box.hidden=false;box.replaceChildren();const title=document.createElement("h4");title.textContent="คัดขนาดเข็มจากแรงแกนแนวดิ่ง";box.append(title);const line=(label,value,warning=false)=>{const p=document.createElement("p");p.textContent=label+" "+value;if(warning)p.className="nR20-alert";box.append(p)};line("แกนของโมเดล:","Y แนวดิ่ง (Y ขึ้น); R บวกคือแรงอัดที่หัวเข็ม · Z เป็นแนวกว้าง");line("แรงอัดสูงสุดใต้แรงใช้งาน (ASD) ต่อเข็ม:",peak?fmt(peak.R)+" kN · "+peak.caseId+" / "+peak.id:"ไม่มีกรณี ASD ที่มีแรงอัด");line("กำลังอัดใช้งานที่กรอก (Safe load):",Number.isFinite(rated)?fmt(rated)+" kN/ต้น":"ยังไม่ระบุ");line("ผลเทียบ:",status+(Number.isFinite(dc)?" · D/C "+fmt(dc):""),dc>1);line("แรงถอนสูงสุดใต้แรงใช้งาน (ASD):",lift?fmt(-lift.R)+" kN · "+lift.caseId+" / "+lift.id:"ไม่พบในกรณีที่ตรวจ");line("ที่มา:",source||"ยังไม่ได้ระบุผู้ผลิต รุ่น และหน้าเอกสาร");line("ขอบเขต:","ไม่ต้องมี boring log เพื่อคัดขนาดจากแรงอัดนี้; กำลังในแค็ตตาล็อกต้องตรงเงื่อนไขใช้งาน และผลนี้ไม่ตรวจแรงด้านข้าง/กลุ่มเข็ม/การทรุดตัว")}document.addEventListener("click",e=>{if(["n53CheckPiles","cp025Calculate","n53PileConfirm"].includes(e.target.closest?.("button")?.id))setTimeout(draw,250)},true);const mo=new MutationObserver(()=>{if(q("n53PileEditor")&&!q("nR20PileAxial"))draw()});mo.observe(document.documentElement,{childList:true,subtree:true});draw()})();

