window.NCYR21Persistence=window.NCYSource.createProjectArchive();(()=>{"use strict";const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);const labels={"Pile compression / ASD":"เข็มรับแรงอัดใช้งาน (ASD)","Pile compression ASD":"เข็มรับแรงอัดใช้งาน (ASD)","Pile tension ASD":"เข็มรับแรงถอนใช้งาน (ASD)","Concrete tension breakout 41":"คอนกรีตแตกหลุดจากแรงดึงสลัก","Tension breakout41":"คอนกรีตแตกหลุดจากแรงดึงสลัก","Pullout41":"สลักหลุดถอน","Anchor T+V42":"สลักรับแรงดึงร่วมแรงเฉือน","Pryout42":"คอนกรีตแตกงัด","Shear breakout43":"คอนกรีตแตกหลุดจากแรงเฉือน","Pile compression / SLS":"กำลังอัดเข็มที่ระดับใช้งาน","Pile compression SLS":"กำลังอัดเข็มที่ระดับใช้งาน","Pile tension SLS":"กำลังรับแรงถอนเข็มที่ระดับใช้งาน","Side-face blowout48":"คอนกรีตแตกด้านข้างจากหัวสลัก","Anchor N+V 17.6":"แรงดึงร่วมแรงเฉือนของคอนกรีตรอบสลัก","Base friction V+T48":"แรงเสียดทานรับแรงเฉือนและแรงบิดที่ฐาน","WIND/STABILITY":"แรงลมและเสถียรภาพ","HEAD CONNECTION":"จุดต่อหัวป้าย","ANCHOR/PLATE":"สลักยึดและเพลทฐาน","RC/GEOTECH":"ฐานคอนกรีตและเสาเข็ม","W2/W3/W4 and local wall/stiffener":"แนวเชื่อม ผนังท่อ และแผ่นค้ำ","Plate tension/prying and anchor/contact compatibility":"เพลทด้านดึงและการถ่ายแรงเข้าสลัก","SECTIONAL_ASSUMPTION_NO_LOCAL_SLAB_FEM":"ขอบเขตการวิเคราะห์ฐานเฉพาะหน้าตัด","ECCENTRIC_PUNCHING_COLUMN_AND_PILES":"เจาะทะลุจากแรงเยื้องศูนย์","PEDESTAL_RC_AND_DOWELS":"ตอม่อและเดือยเหล็ก","PILE_HEAD_ANCHORAGE_UPLIFT":"การยึดหัวเข็มรับแรงถอน","IN_PLANE_SHEAR_TORSION":"แรงเฉือนในระนาบและแรงบิด","STM_LOCAL_NODAL_AND_CONGESTION":"แนวถ่ายแรง โหนด และความหนาแน่นเหล็ก","PROJECT_LOAD_MATERIAL_SITE_VERIFICATION":"ข้อมูลแรง วัสดุ และพื้นที่จริง","Pile/geotechnical capacity and project wind applicability":"เงื่อนไขกำลังเข็มและการใช้วิธีแรงลม"};function action(id){if(/pile.*compression/i.test(id))return"ระบุรุ่นและกำลังอัดใช้งาน (Safe load) ของผู้ผลิต พร้อมที่มา แล้วคำนวณซ้ำ";if(/breakout|pullout|pryout|Anchor T\+V|ANCHOR\/PLATE/i.test(id))return"ตรวจชนิดสลัก ระยะฝังใช้งาน ระยะขอบ และฐานวิธีกำลังที่ตรงกับผลิตภัณฑ์";if(/WIND\/STABILITY/i.test(id))return"ตรวจขอบเขตแรงลมและเสถียรภาพที่วิธีปัจจุบันยังไม่ครอบคลุม";if(/HEAD CONNECTION|local wall|stiffener|W2\/W3|prying/i.test(id))return"ตรวจรายละเอียดและกำลังจุดต่อส่วนที่ยังไม่มีผล";if(/RC\/GEOTECH/i.test(id))return"ดูผลฐาน RC ที่คำนวณแล้ว และปิดกลไกฐาน/เข็มที่ยังขาดตามแรงจริง";return"เปิดผลตรวจเพื่อดูข้อมูลที่ขาด ขอบเขตวิธี และกรณีควบคุม"}function rows(a){return[...a.failed.map(x=>({kind:"NG",label:x.id,detail:"D/C "+x.dc.toFixed(3)+" · "+(x.caseId||"—"),next:"ปรับขนาดหรือรายละเอียดของรายการนี้ แล้วคำนวณซ้ำ"})),...a.invalid.map(x=>({kind:"ไม่มีผล",label:x.id,detail:"ยังไม่มีค่ากำลังที่ใช้เทียบได้",next:action(x.id)})),...a.open.map(x=>({kind:"ขอบเขตยังไม่ครบ",label:x,detail:"ยังไม่ยืนยันว่าผ่านทั้งระบบ",next:action(x)}))]}function html(a,rank){const rs=rows(a);if(!rs.length)return"";return`<section class="r21-blockers" aria-label="รายการที่ต้องแก้ก่อนเลือกชุดผ่าน"><h4>รายการที่ต้องแก้ก่อนเลือกชุดผ่าน</h4><p>เกินเกณฑ์ ${a.failed.length} รายการ · ไม่มีผล ${a.invalid.length} รายการ · ขอบเขตยังไม่ครบ ${a.open.length} รายการ</p><p>${esc(rank.reason)}</p><details class="r55-blocker-more"><summary>ดูรายการทั้งหมด (${rs.length})</summary><div class="r21-blocker-scroll"><table><thead><tr><th>รายการ / สถานะ</th><th>ผลที่พบ</th><th>แก้ต่ออย่างไร</th></tr></thead><tbody>${rs.map(x=>`<tr><td><b>${esc(x.kind)}</b><br>${esc(labels[x.label]||x.label)}</td><td>${esc(x.detail)}</td><td data-label="แก้ต่อ: ">${esc(x.next)}</td></tr>`).join("")}</tbody></table></div></details><button type="button" data-r21-open-review>เปิดรายละเอียดตรวจและข้อมูลที่ใช้</button></section>`}window.NCYR21Blockers=Object.freeze({html,rows});const css=document.createElement("style");css.textContent=".r21-blockers{margin:14px 0;padding:12px;border:1px solid #d6e0e8;border-radius:10px;background:#fff}.r21-blockers h4{margin:0 0 8px;font-size:14px}.r21-blocker-scroll{overflow:auto;max-height:320px}.r21-blockers table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}.r21-blockers td,.r21-blockers th{padding:8px;vertical-align:top;border-bottom:1px solid #e5ebf0}.r21-blockers th{background:#f1f5f8}.r21-blockers button{margin-top:10px;min-height:40px}@media(max-width:650px){.r21-blockers table,.r21-blockers tbody,.r21-blockers tr,.r21-blockers td{display:block;width:100%!important;min-width:0!important;max-width:100%!important;box-sizing:border-box;overflow-wrap:anywhere}.r21-blockers thead{display:none}.r21-blockers tr{border-bottom:1px solid #d6e0e8;padding:6px 0}.r21-blockers td{border:0;padding:4px 6px;white-space:normal!important}.r21-blockers td[data-label]:before{content:attr(data-label);font-weight:600}}@media print{.r21-blockers{display:none!important}}";document.head.append(css);document.addEventListener("click",e=>{if(!e.target.closest?.("[data-r21-open-review]"))return;document.getElementById("nR17Review")?.click()})})();
